def _unb85(s):
    """Decode one embedded asset blob: base85 text of zlib-compressed bytes."""
    return zlib.decompress(base64.b85decode(s.encode()))


def parse_atlas(raw):
    assert raw[:3] == b"NA1"
    pos = 3
    styles = {}
    while pos < len(raw):
        nlen = raw[pos]
        pos += 1
        name = raw[pos:pos + nlen].decode()
        pos += nlen
        ascent, line_h, count = struct.unpack_from("<HHH", raw, pos)
        pos += 6
        glyphs = {}
        for _ in range(count):
            cp, adv, bx, by, gw, gh = struct.unpack_from("<HbbbBB", raw, pos)
            pos += 7
            alpha = raw[pos:pos + gw * gh]
            pos += gw * gh
            rows = []
            for r in range(gh):
                row = alpha[r * gw:(r + 1) * gw]
                runs = []
                x = 0
                while x < gw:
                    a = row[x]
                    if a == 0:
                        x += 1
                        continue
                    if a == 255:
                        x0 = x
                        while x < gw and row[x] == 255:
                            x += 1
                        runs.append((x0, x, None))
                    else:
                        x0 = x
                        while x < gw and row[x] not in (0, 255):
                            x += 1
                        runs.append((x0, x, row[x0:x]))
                rows.append(runs)
            glyphs[cp] = (adv, bx, by, gw, gh, rows)
        styles[name] = (ascent, line_h, glyphs)
    return styles


def parse_sprites(raw):
    assert raw[:3] == b"NS1"
    count = struct.unpack_from("<H", raw, 3)[0]
    pos = 5
    sprites = {}
    for _ in range(count):
        nlen = raw[pos]
        pos += 1
        name = raw[pos:pos + nlen].decode()
        pos += nlen
        w, h = struct.unpack_from("<HH", raw, pos)
        pos += 4
        sprites[name] = (w, h, raw[pos:pos + w * h * 3])
        pos += w * h * 3
    return sprites


def parse_land(raw):
    w, h = struct.unpack_from("<HH", raw, 0)
    return w, h, raw[4:4 + w * h]


class Canvas:
    def __init__(self, w, h, bg):
        self.w, self.h = w, h
        self.px = bytearray(bytes(bg) * (w * h))

    def fill_rect(self, x0, y0, x1, y1, color):
        x0, y0 = max(0, int(x0)), max(0, int(y0))
        x1, y1 = min(self.w, int(x1)), min(self.h, int(y1))
        if x1 <= x0 or y1 <= y0:
            return
        row = bytes(color) * (x1 - x0)
        for y in range(y0, y1):
            off = (y * self.w + x0) * 3
            self.px[off:off + len(row)] = row

    def outline_rect(self, x0, y0, x1, y1, color, t=1):
        self.fill_rect(x0, y0, x1, y0 + t, color)
        self.fill_rect(x0, y1 - t, x1, y1, color)
        self.fill_rect(x0, y0, x0 + t, y1, color)
        self.fill_rect(x1 - t, y0, x1, y1, color)

    def set_px(self, x, y, color):
        if 0 <= x < self.w and 0 <= y < self.h:
            off = (y * self.w + x) * 3
            self.px[off:off + 3] = bytes(color)

    def fill_circle(self, cx, cy, r, color):
        for dy in range(-r, r + 1):
            span = int(math.sqrt(max(0, r * r - dy * dy)))
            self.fill_rect(cx - span, cy + dy, cx + span + 1, cy + dy + 1, color)

    def paste_sprite(self, sprite, dx, dy, dw=None, dh=None):
        sw, sh, data = sprite
        dw = dw or sw
        dh = dh or sh
        for j in range(dh):
            sy = min(sh - 1, j * sh // dh)
            y = dy + j
            if y < 0 or y >= self.h:
                continue
            if dw == sw:
                off = (y * self.w + dx) * 3
                self.px[off:off + sw * 3] = data[sy * sw * 3:(sy + 1) * sw * 3]
            else:
                for i in range(dw):
                    sx = min(sw - 1, i * sw // dw)
                    so = (sy * sw + sx) * 3
                    self.set_px(dx + i, y, (data[so], data[so + 1], data[so + 2]))

    def draw_land(self, land, dx, dy, dw, dh, sea_color, land_color):
        lw, lh, mask = land
        self.fill_rect(dx, dy, dx + dw, dy + dh, sea_color)
        land_b = bytes(land_color)
        for j in range(dh):
            sy = min(lh - 1, j * lh // dh)
            y = dy + j
            base = sy * lw
            run_start = None
            for i in range(dw + 1):
                is_land = False
                if i < dw:
                    sx = min(lw - 1, i * lw // dw)
                    is_land = mask[base + sx] > 127
                if is_land and run_start is None:
                    run_start = i
                elif not is_land and run_start is not None:
                    off = (y * self.w + dx + run_start) * 3
                    n = (i - run_start) * 3
                    self.px[off:off + n] = land_b * (i - run_start)
                    run_start = None


# ---------------- text ----------------

STYLES = {}


def text_w(style, s, tracking=0):
    _, _, glyphs = STYLES[style]
    total = 0
    for ch in s:
        g = glyphs.get(ord(ch))
        total += (g[0] if g else 6) + tracking
    return total - (tracking if s else 0)


def draw_text(cv, x, baseline, s, style, color, tracking=0):
    ascent, _, glyphs = STYLES[style]
    cr, cg, cb = color
    pen = int(x)
    for ch in s:
        g = glyphs.get(ord(ch))
        if g is None:
            pen += 6 + tracking
            continue
        adv, bx, by, gw, gh, rows = g
        gx = pen + bx
        gy = baseline - ascent + by
        for r, runs in enumerate(rows):
            y = gy + r
            if y < 0 or y >= cv.h:
                continue
            for x0, x1, alphas in runs:
                if alphas is None:
                    cv.fill_rect(gx + x0, y, gx + x1, y + 1, color)
                else:
                    for i, a in enumerate(alphas):
                        px_x = gx + x0 + i
                        if 0 <= px_x < cv.w and a:
                            off = (y * cv.w + px_x) * 3
                            ia = 255 - a
                            cv.px[off] = (cr * a + cv.px[off] * ia) // 255
                            cv.px[off + 1] = (cg * a + cv.px[off + 1] * ia) // 255
                            cv.px[off + 2] = (cb * a + cv.px[off + 2] * ia) // 255
        pen += adv + tracking
    return pen


def draw_text_center(cv, cx, baseline, s, style, color, tracking=0):
    w = text_w(style, s, tracking)
    return draw_text(cv, cx - w // 2, baseline, s, style, color, tracking)


def draw_text_right(cv, x_right, baseline, s, style, color, tracking=0):
    w = text_w(style, s, tracking)
    return draw_text(cv, x_right - w, baseline, s, style, color, tracking)


def wrap(style, s, max_w, tracking=0):
    lines = []
    cur = ""
    for word in s.split():
        trial = word if not cur else cur + " " + word
        if text_w(style, trial, tracking) <= max_w or not cur:
            cur = trial
        else:
            lines.append(cur)
            cur = word
    if cur:
        lines.append(cur)
    return lines


def draw_para(cv, x, baseline, s, style, color, max_w, line_h, max_lines=99):
    lines = wrap(style, s, max_w)[:max_lines]
    y = baseline
    for ln in lines:
        draw_text(cv, x, y, ln, style, color)
        y += line_h
    return y


# ---------------- PNG output ----------------

def write_png(path, cv):
    raw = bytearray()
    stride = cv.w * 3
    for y in range(cv.h):
        raw.append(0)
        raw += cv.px[y * stride:(y + 1) * stride]

    def chunk(tag, data):
        c = struct.pack(">I", len(data)) + tag + data
        c += struct.pack(">I", zlib.crc32(tag + data) & 0xFFFFFFFF)
        return c

    png = b"\x89PNG\r\n\x1a\n"
    png += chunk(b"IHDR", struct.pack(">IIBBBBB", cv.w, cv.h, 8, 2, 0, 0, 0))
    png += chunk(b"IDAT", zlib.compress(bytes(raw), 9))
    png += chunk(b"IEND", b"")
    with open(path, "wb") as f:
        f.write(png)


