# ---------------- layout ----------------

LON0, LON1, LAT0, LAT1 = -172.0, 196.0, 78.0, -58.0


def fit_text(style, s, max_w, tracking=0):
    if text_w(style, s, tracking) <= max_w:
        return s
    while len(s) > 4 and text_w(style, s + "\u2026", tracking) > max_w:
        s = s[:-1]
    return s + "\u2026"


def pin_xy(lon, lat, mx, my, mw, mh):
    x = mx + (lon - LON0) / (LON1 - LON0) * mw
    y = my + (LAT0 - lat) / (LAT0 - LAT1) * mh
    return int(x), int(y)


def draw_pin(cv, x, y, num, color):
    r = 8 if num >= 10 else 7
    cv.fill_circle(x, y, r, color)
    draw_text_center(cv, x, y + 3, str(num), "pin", PAPER)


